function profileCapacity(state) {
	if (!state.billingEnabled) return { kind: "unlimited" };
	if (state.locked) return { kind: "locked" };
	if (state.status === "none" || state.status === "canceled") return { kind: "subscription-required" };
	if (state.status === "comped") return { kind: "unlimited" };
	const limit = state.status === "trialing" ? Math.max(10, state.slots) : state.slots;
	return {
		kind: "limited",
		limit,
		used: state.usedSlots,
		remaining: Math.max(0, limit - state.usedSlots)
	};
}
