//#region apps/web/src/features/portfolio/relationships/directory-queries.ts
function useTargetDirectory(kind, query, page, committeeId) {
	const api = useApi();
	return useQuery({
		queryKey: [
			"target-directory",
			kind,
			query,
			page,
			committeeId
		],
		enabled: Boolean(query.trim() || committeeId),
		queryFn: async ({ signal }) => {
			const options = { signal };
			const search = queryString({
				q: query.trim(),
				page,
				pageSize: 20
			});
			if (kind === "congress") {
				const data = await api.request("core", `directory/contacts?${search}`, memberSearchSchema, options);
				return {
					...data,
					rows: data.contacts.map((row) => ({
						id: row.id,
						name: row.fullName,
						title: row.title,
						meta: [
							row.chamber,
							row.state,
							row.party
						].filter(Boolean).join(" · "),
						directory: "congress"
					}))
				};
			}
			if (kind === "state") {
				const data = await api.request("core", `explorer/state-legislators?${search}&activeOnly=true`, stateSearchSchema, options);
				return {
					total: data.total,
					page,
					pageSize: 20,
					rows: data.rows.map((row) => ({
						id: row.id,
						name: row.name,
						title: "State legislator",
						meta: [
							row.state,
							row.chamber,
							row.district,
							row.party
						].filter(Boolean).join(" · "),
						directory: "state",
						current: true
					}))
				};
			}
			if (kind === "committee") {
				if (!committeeId) return {
					rows: [],
					total: 0,
					page: 1,
					pageSize: 20
				};
				const data = await api.request("core", `directory/committees/${encodeURIComponent(committeeId)}/staff?${search}`, committeeStaffSchema.refine((result) => result.committee?.id === committeeId && result.staff.every((row) => row.committee.id === committeeId), "Committee association mismatch"), options);
				return {
					...data,
					rows: data.staff.map((row) => ({
						id: row.id,
						name: row.fullName,
						title: row.title,
						meta: row.committee.name,
						directory: "staff",
						current: row.isCurrent
					}))
				};
			}
			const data = await api.request("core", `directory/people?${search}&personType=staff&current=true`, peopleSearchSchema, options);
			return {
				...data,
				rows: data.people.map((row) => ({
					id: row.id,
					name: row.fullName,
					title: row.title,
					meta: [row.state, row.party].filter(Boolean).join(" · "),
					directory: "staff",
					current: row.isCurrent
				}))
			};
		}
	});
}
